/**
 * rental.js
 * Handles vehicle sales: Razorpay order creation/verification, purchase history,
 * command-center/franchise handover, customer purchased vehicles and invoices.
 * The filename is retained for backwards compatibility with the existing project.
 */
const crypto     = require('crypto');
const nodemailer = require('nodemailer');
const M = require('../models');
const { VehicleRental, PendingVehicle, Invoice, User, Financial, Job } = M;
const audit = require('../services/audit');

// ── Razorpay helper ──────────────────────────────────────────────────
function getRazorpay() {
  const Razorpay = require('razorpay');
  return new Razorpay({
    key_id:     process.env.RAZORPAY_KEY_ID,
    key_secret: process.env.RAZORPAY_KEY_SECRET,
  });
}

// ── Email transporter ────────────────────────────────────────────────
function getMailer() {
  return nodemailer.createTransport({
    host:   process.env.SMTP_HOST,
    port:   Number(process.env.SMTP_PORT || 587),
    secure: process.env.SMTP_SECURE === 'true',
    auth:   { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS },
  });
}

// ── Invoice number generator ─────────────────────────────────────────
function invoiceNo() {
  return `INV-SALE-${Date.now()}`;
}

